<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if(!events_schema_ready())redirect('upgrade-events.php');$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM events WHERE id=?');$s->execute([$id]);$event=$s->fetch();if(!$event||!can_manage_event($event)){http_response_code(403);exit('You cannot manage this event.');}$tab=$_GET['tab']??'overview';$allowed=['overview','details','schedule','speakers','attendees','relationships','media','settings'];if(!in_array($tab,$allowed,true))$tab='overview';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='save_details'){db()->prepare('UPDATE events SET title=?,slug=?,subtitle=?,description=?,event_type=? WHERE id=?')->execute([trim($_POST['title']),event_slug(trim($_POST['title']),$id),trim($_POST['subtitle']),trim($_POST['description']),$_POST['event_type'],$id]);$banner=save_event_image('banner','banners',$id);if($banner)db()->prepare('UPDATE events SET banner_path=? WHERE id=?')->execute([$banner,$id]);flash('success','Event details saved.');$tab='details';}elseif($action==='save_schedule'){db()->prepare('UPDATE events SET starts_at=?,ends_at=?,timezone=?,format=?,venue_name=?,address1=?,city=?,state_region=?,postal_code=?,country=?,virtual_url=? WHERE id=?')->execute([str_replace('T',' ',$_POST['starts_at']),str_replace('T',' ',$_POST['ends_at']),trim($_POST['timezone']),$_POST['format'],trim($_POST['venue_name']),trim($_POST['address1']),trim($_POST['city']),trim($_POST['state_region']),trim($_POST['postal_code']),trim($_POST['country']),trim($_POST['virtual_url']),$id]);flash('success','Schedule and location saved.');$tab='schedule';}elseif($action==='add_speaker'){db()->prepare('INSERT INTO event_speakers(event_id,name,role,bio,sort_order) VALUES(?,?,?,?,?)')->execute([$id,trim($_POST['name']),trim($_POST['role']),trim($_POST['bio']),(int)($_POST['sort_order']??0)]);flash('success','Speaker added.');$tab='speakers';}elseif($action==='delete_speaker'){db()->prepare('DELETE FROM event_speakers WHERE id=? AND event_id=?')->execute([(int)$_POST['speaker_id'],$id]);flash('success','Speaker removed.');$tab='speakers';}elseif($action==='attendee_status'){db()->prepare('UPDATE event_attendees SET attendee_status=?,checked_in_at=IF(?="checked_in",NOW(),checked_in_at) WHERE id=? AND event_id=?')->execute([$_POST['attendee_status'],$_POST['attendee_status'],(int)$_POST['attendee_id'],$id]);flash('success','Attendee updated.');$tab='attendees';}elseif($action==='add_relationship'){db()->prepare('INSERT IGNORE INTO event_relationships(event_id,entity_type,entity_id) VALUES(?,?,?)')->execute([$id,$_POST['entity_type'],(int)$_POST['entity_id']]);flash('success','Relationship added.');$tab='relationships';}elseif($action==='delete_relationship'){db()->prepare('DELETE FROM event_relationships WHERE id=? AND event_id=?')->execute([(int)$_POST['relationship_id'],$id]);flash('success','Relationship removed.');$tab='relationships';}elseif($action==='save_settings'){db()->prepare('UPDATE events SET visibility=?,capacity=?,registration_mode=?,waitlist_enabled=?,comments_enabled=? WHERE id=?')->execute([$_POST['visibility'],(int)($_POST['capacity']??0)?:null,$_POST['registration_mode'],isset($_POST['waitlist_enabled'])?1:0,isset($_POST['comments_enabled'])?1:0,$id]);flash('success','Event settings saved.');$tab='settings';}}catch(Throwable $e){flash('error',$e->getMessage());}redirect_route('events/manage.php',['id'=>$id,'tab'=>$tab]);}
$s=db()->prepare('SELECT * FROM events WHERE id=?');$s->execute([$id]);$event=$s->fetch();$speakers=event_speakers($id);$attendees=db()->prepare('SELECT a.*,u.display_name,u.email FROM event_attendees a JOIN users u ON u.id=a.user_id WHERE a.event_id=? ORDER BY a.registered_at DESC');$attendees->execute([$id]);$attendees=$attendees->fetchAll();$rels=event_relationships($id);$counts=db()->prepare("SELECT COUNT(*) registrations,SUM(attendee_status='checked_in') checked_in FROM event_attendees WHERE event_id=? AND attendee_status<>'cancelled'");$counts->execute([$id]);$counts=$counts->fetch();app_header('Manage '.$event['title']);?>
<section class="dashboard-hero"><p class="eyebrow">EVENT MANAGEMENT</p><h1><?=e($event['title'])?></h1><p><span class="status-badge status-<?=e($event['status'])?>"><?=e(ucfirst($event['status']))?></span> <a class="button ghost" href="dashboard.php">My Events</a><?php if($event['status']==='approved'):?> <a class="button ghost" href="view.php?slug=<?=urlencode($event['slug'])?>">Public Page</a><?php endif?></p></section><nav class="management-tabs"><?php foreach($allowed as $t):?><a class="<?=$tab===$t?'active':''?>" href="?id=<?=$id?>&tab=<?=$t?>"><?=e(ucfirst($t))?></a><?php endforeach?></nav>
<?php if($tab==='overview'):?><section class="dashboard-grid"><article class="app-card"><h2>Registrations</h2><div class="metric"><?=(int)$counts['registrations']?></div></article><article class="app-card"><h2>Checked In</h2><div class="metric"><?=(int)$counts['checked_in']?></div></article><article class="app-card"><h2>Schedule</h2><p><?=e(event_date_label($event))?></p></article><article class="app-card"><h2>Next Action</h2><p><?=$event['status']==='pending'?'Awaiting administrator approval.':'Continue preparing speakers, relationships, and attendee settings.'?></p></article></section>
<?php elseif($tab==='details'):?><section class="form-card"><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_details"><label class="full">Title<input name="title" value="<?=e($event['title'])?>" required></label><label class="full">Subtitle<input name="subtitle" value="<?=e($event['subtitle'])?>"></label><label>Type<select name="event_type"><?php foreach(event_type_options() as $k=>$v):?><option value="<?=e($k)?>" <?=$event['event_type']===$k?'selected':''?>><?=e($v)?></option><?php endforeach?></select></label><label>Banner<input type="file" name="banner" accept="image/*"></label><label class="full">Description<textarea name="description" rows="10"><?=e($event['description'])?></textarea></label><div class="full"><button class="button primary">Save Details</button></div></form></section>
<?php elseif($tab==='schedule'):?><section class="form-card"><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_schedule"><label>Starts<input type="datetime-local" name="starts_at" value="<?=e(date('Y-m-d\TH:i',strtotime($event['starts_at'])))?>"></label><label>Ends<input type="datetime-local" name="ends_at" value="<?=e(date('Y-m-d\TH:i',strtotime($event['ends_at'])))?>"></label><label>Timezone<input name="timezone" value="<?=e($event['timezone'])?>"></label><label>Format<select name="format"><?php foreach(['virtual','physical','hybrid'] as $v):?><option <?=$event['format']===$v?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label>Venue / room<input name="venue_name" value="<?=e($event['venue_name'])?>"></label><label>Address<input name="address1" value="<?=e($event['address1'])?>"></label><label>City<input name="city" value="<?=e($event['city'])?>"></label><label>State / region<input name="state_region" value="<?=e($event['state_region'])?>"></label><label>Postal code<input name="postal_code" value="<?=e($event['postal_code'])?>"></label><label>Country<input name="country" value="<?=e($event['country'])?>"></label><label class="full">Virtual URL<input type="url" name="virtual_url" value="<?=e($event['virtual_url'])?>"></label><div class="full"><button class="button primary">Save Schedule</button></div></form></section>
<?php elseif($tab==='speakers'):?><section class="two-column"><div class="form-card"><h2>Add Speaker or Guest</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="add_speaker"><label>Name<input name="name" required></label><label>Role<input name="role" value="Speaker"></label><label class="full">Bio<textarea name="bio"></textarea></label><label>Sort order<input type="number" name="sort_order" value="0"></label><div class="full"><button class="button primary">Add Speaker</button></div></form></div><div><?php foreach($speakers as $sp):?><article class="app-card"><h3><?=e($sp['name'])?></h3><p><?=e($sp['role'])?></p><p><?=e($sp['bio'])?></p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete_speaker"><input type="hidden" name="speaker_id" value="<?=$sp['id']?>"><button class="button danger">Remove</button></form></article><?php endforeach?></div></section>
<?php elseif($tab==='attendees'):?><section class="form-card"><h2>Attendees</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Status</th><th>Registered</th><th>Update</th></tr></thead><tbody><?php foreach($attendees as $a):?><tr><td><?=e($a['display_name'])?></td><td><?=e($a['email'])?></td><td><?=e($a['attendee_status'])?></td><td><?=e($a['registered_at'])?></td><td><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="attendee_status"><input type="hidden" name="attendee_id" value="<?=$a['id']?>"><select name="attendee_status"><?php foreach(['registered','waitlisted','approved','checked_in','cancelled'] as $v):?><option <?=$a['attendee_status']===$v?'selected':''?>><?=$v?></option><?php endforeach?></select><button class="button ghost">Save</button></form></td></tr><?php endforeach?></tbody></table></div></section>
<?php elseif($tab==='relationships'):?><?php $entities=event_relationship_choices();?><section class="two-column"><div class="form-card"><h2>Connect Event</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="add_relationship"><label>Entity type<select name="entity_type" id="entityType"><?php foreach($entities as $type=>$rows):?><option value="<?=e($type)?>"><?=e(ucfirst($type))?></option><?php endforeach?></select></label><label>Entity<select name="entity_id" id="entityId"><?php foreach($entities as $type=>$rows):?><?php foreach($rows as $row):?><option data-type="<?=e($type)?>" value="<?=$row['id']?>"><?=e(ucfirst($type).': '.$row['name'])?></option><?php endforeach?><?php endforeach?></select></label><div class="full"><button class="button primary">Add Relationship</button></div></form></div><div><?php foreach($rels as $r):?><article class="app-card"><h3><?=e($r['entity_name'])?></h3><p><?=e(ucfirst($r['entity_type']))?></p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete_relationship"><input type="hidden" name="relationship_id" value="<?=$r['id']?>"><button class="button danger">Remove</button></form></article><?php endforeach?></div></section>
<?php elseif($tab==='media'):?><section class="form-card"><h2>Media</h2><p>Banner uploads are available under Details. Gallery, attachments, livestreams, and recordings use the installed event_media table and will be expanded during acceptance testing.</p></section>
<?php elseif($tab==='settings'):?><section class="form-card"><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_settings"><label>Visibility<select name="visibility"><?php foreach(['public','members','private'] as $v):?><option <?=$event['visibility']===$v?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label>Capacity<input type="number" min="1" name="capacity" value="<?=e((string)$event['capacity'])?>"></label><label>Registration mode<select name="registration_mode"><?php foreach(['open','approval','invite','closed'] as $v):?><option <?=$event['registration_mode']===$v?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label><input type="checkbox" name="waitlist_enabled" <?=$event['waitlist_enabled']?'checked':''?>> Enable waitlist</label><label><input type="checkbox" name="comments_enabled" <?=$event['comments_enabled']?'checked':''?>> Enable comments</label><div class="full"><button class="button primary">Save Settings</button></div></form></section><?php endif?><?php app_footer();
